(2, 'ORDER_PAID', '订单支付成功', 'NONE', '{"fields": [{"key": "orderId", "desc": "订单号", "type": "string"}]}', 1, 0, 1, '🔴 必须带 eventBizId=订单号，否则同一天多笔订单只会算一笔', 1, NULL, '2026-08-01 05:12:16', NULL, '2026-08-22 09:49:51'),
